class Solution {
  shipWithinDays(weights, max_days) {
    let low = Math.max(...weights); // If we pick low as less than max, then we never ship the max weights
    let high = weights.reduce((acc, curr) => (acc += curr), 0); // We can ship all in one day by summing all weights
    let ans = -1;
    const n = weights.length;
    while (low <= high) {
      const mid = Math.floor((low + high) / 2); // mid,is the maximum capacity we can ship
      let days = 1;
      let load = 0;
      for (let i = 0; i < n; i++) {
        load = load + weights[i];
        if (load <= mid) {
          continue;
        } else {
          days++;
          load = weights[i];
        }
      }
      if (days <= max_days) {
        ans = mid;
        high = mid - 1;
      } else {
        low = mid + 1;
      }
    }
    return ans;
  }
}

